// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string" ? csvRaw : JSON.stringify(csvRaw))
  .replace(/^\uFEFF/, "");

// Separa linhas e remove linhas vazias
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(";").map(h => h.trim());

// Converte cada linha em objeto
const investimentos = lines.slice(1).map(line => {
  const cols = line.split(";").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza número para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return { json: { investimentos } };

// Tabela de produtos de investimento por perfil
const produtosInvestimento = [
  { perfil: "Conservador", produto: "Poupança", minimo: 100, rentabilidade: "6.2%" },
  { perfil: "Conservador", produto: "CDB Liquidez Diária", minimo: 1000, rentabilidade: "12.5%" },
  { perfil: "Conservador", produto: "Tesouro Selic", minimo: 500, rentabilidade: "11.0%" },
  { perfil: "Moderado", produto: "CDB Prefixado", minimo: 1000, rentabilidade: "14.0%" },
  { perfil: "Moderado", produto: "Fundo Multimercado", minimo: 5000, rentabilidade: "16.0%" },
  { perfil: "Moderado", produto: "Tesouro IPCA+", minimo: 1000, rentabilidade: "IPCA+6.0%" },
  { perfil: "Arrojado", produto: "Ações ETF", minimo: 500, rentabilidade: "Variável" },
  { perfil: "Arrojado", produto: "Fundo de Ações", minimo: 10000, rentabilidade: "Variável" },
  { perfil: "Arrojado", produto: "Criptomoedas", minimo: 100, rentabilidade: "Variável" }
];

// Função para converter "R$ 12.500,00" para número (12500)
function converterSaldoParaNumero(saldoTexto) {
  if (typeof saldoTexto === 'number') return saldoTexto;
  if (!saldoTexto) return 0;

  const limpo = String(saldoTexto)
    .replace(/[R$\s.]/g, '')
    .replace(',', '.');

  return parseFloat(limpo) || 0;
}

// Processa um único cliente
function processarCliente(cliente) {
  const nome = cliente.nome || cliente.Nome || 'Cliente';
  const email = cliente.email || cliente.Email || '';
  const perfil = cliente.perfil || cliente.Perfil || 'Conservador';
  const saldoTexto = cliente.saldo || cliente.Saldo || 'R$ 0,00';
  const saldoNum = converterSaldoParaNumero(saldoTexto);

  const opcoesPerfil = produtosInvestimento.filter(
    inv => inv.perfil === perfil
  );

  let recomendacao = opcoesPerfil.find(
    inv => saldoNum >= inv.minimo
  );

  let motivo = "saldo_ok";

  if (!recomendacao && opcoesPerfil.length > 0) {
    recomendacao = opcoesPerfil.reduce(
      (prev, curr) => prev.minimo < curr.minimo ? prev : curr
    );
    motivo = "saldo_insuficiente";
  }

  const prodNome = recomendacao ? recomendacao.produto : "Nenhum";
  const minVal = recomendacao ? recomendacao.minimo : 0;
  const rent = recomendacao ? recomendacao.rentabilidade : "N/A";

  const minFormatado = minVal.toLocaleString(
    'pt-BR',
    { minimumFractionDigits: 2 }
  );

  const mensagens = [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${prodNome}** (mínimo R$ ${minFormatado}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${rent}.`,
    `Oi ${nome}! Recomendação para perfil ${perfil}: **${prodNome}** (mínimo R$ ${minFormatado}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${rent}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${prodNome}** (mínimo R$ ${minFormatado}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${rent}.`
  ];

  return {
    nome: nome,
    email: email,
    perfil: perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    Recomendacao: {
      perfil: perfil,
      produto: prodNome,
      minimo: minVal,
      rentabilidade: rent
    },
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: mensagens[0]
  };
}

// Captura e extração automática da lista de clientes
const itensEntrada = $input.all();
let listaClientes = [];

for (const item of itensEntrada) {
  const json = item.json;

  // Os dados podem vir dentro de json.body
  const dados = json.body || json;

  if (Array.isArray(dados)) {
    listaClientes.push(...dados);
  } else if (Array.isArray(dados.clientes)) {
    listaClientes.push(...dados.clientes);
  } else if (Array.isArray(dados.data)) {
    listaClientes.push(...dados.data);
  } else if (typeof dados === 'object') {
    listaClientes.push(dados);
  }
}

// Retorna cada cliente como um item separado no n8n
return listaClientes.map(cliente => ({
  json: processarCliente(cliente)
}));

